
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_ccdf_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_ccdf", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.312176243705221e-02, -4.252728798822597e-02, -4.151104743945395e-02, -3.967956576716094e-02, -3.627772555843939e-02, -3.051943494700895e-02, -2.421806331639038e-02, -2.149966920411514e-02, -2.115600634373332e-02, -2.107250564608510e-02, -2.092978389239214e-02, -2.754956767706618e-02, -4.446521741860517e-02, -2.233389211567846e-02, -2.019730619150206e-02, -1.937460234235292e-02, -1.733061778913736e-02, -1.238538611725924e-02, -4.750341055519808e-03, -6.548960022085739e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


